solid.code:
import { Component, JSX, splitProps } from 'solid-js';

export interface AutoGridProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const AutoGrid: Component<AutoGridProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <div
      class={`grid grid-cols-[repeat(auto-fill,minmax(min(100%,280px),1fr))] gap-6 w-full ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </div>
  );
};

